function renderAchievements() {
  elements.achievementList.innerHTML = '';
  elements.achievementList.classList.remove('placeholder');
  const achievements = state.account?.achievements || [];
  if (!achievements.length) {
    elements.achievementList.classList.add('placeholder');
    elements.achievementList.innerHTML = `<div>${t('achievement_empty')}</div>`;
    return;
  }
  achievements.forEach(key => {
    const node = document.createElement('article');
    node.className = 'market-item';
    node.innerHTML = `<strong>${t(`achievement_${key}`)}</strong><small>${state.account.userName}</small>`;
    elements.achievementList.appendChild(node);
  });
}

function renderMarket() {
  elements.marketOverview.innerHTML = '';
  elements.marketEvent.innerHTML = '';
  elements.contractBoard.innerHTML = '';
  const latest = state.room?.market?.[state.room.market.length - 1];
  if (!latest) {
    elements.marketOverview.innerHTML = `<div class="market-item">${t('no_market_data')}</div>`;
  } else {
    [[t('demand'), `${latest.demand} pcs`], [t('avg_price'), `${latest.avgPrice} ₽`], [t('sales'), `${latest.totalSales} pcs`], [t('scenario_label'), state.room.scenarioLabel], [t('day_limit_title'), `${state.room.settings.dayLimit}`]].forEach(([title, value]) => {
      const node = document.createElement('article');
      node.className = 'market-item';
      node.innerHTML = `<strong>${title}</strong><div class="value">${value}</div>`;
      elements.marketOverview.appendChild(node);
    });
  }

  if (state.room?.activeEvent) {
    const event = state.room.activeEvent;
    elements.marketEvent.innerHTML = `<article class="market-item"><strong>${event.label}</strong><div class="value">${event.title}</div><small>${event.description} • ${t('contract_expires')}: ${event.expiresDay}</small></article>`;
  } else {
    elements.marketEvent.innerHTML = `<div class="market-item">${t('no_active_event')}</div>`;
  }

  const contracts = state.room?.contractBoard || [];
  if (!contracts.length) {
    elements.contractBoard.innerHTML = `<div class="market-item">${t('no_contracts')}</div>`;
  } else {
    contracts.forEach(contract => {
      const isAssignedToViewer = contract.assignedPlayerId && contract.assignedPlayerId === state.player?.id;
      const disabled = contract.assignedPlayerId || !canUseBusinessActions() || state.player?.activeContract;
      const node = document.createElement('article');
      node.className = 'market-item';
      node.innerHTML = `<strong>${contract.title}</strong><div class="value">${contract.productLabel} • ${contract.cityLabel}</div><small>${t('contract_progress')}: ${contract.progress}/${contract.targetSales} • ${t('contract_reward')}: ${rub(contract.reward)} ₽ • ${t('contract_expires')}: ${contract.expiresDay}${contract.assignedPlayerName ? ` • ${t('assigned_to')}: ${contract.assignedPlayerName}` : ''}</small>${!contract.completed && !contract.assignedPlayerId ? `<div class="top-gap"><button data-contract-id="${contract.id}" ${disabled ? 'disabled' : ''}>${t('accept_contract')}</button></div>` : isAssignedToViewer ? `<div class="badge-inline-row top-gap"><span class="mini-badge ok">${t('active_contract')}</span></div>` : ''}`;
      elements.contractBoard.appendChild(node);
    });
    elements.contractBoard.querySelectorAll('[data-contract-id]').forEach(button => button.addEventListener('click', () => sendAction('accept-contract', button.dataset.contractId)));
  }

  elements.segmentsOverview.innerHTML = '';
  const segments = state.room?.segments || [];
  if (!segments.length) {
    elements.segmentsOverview.innerHTML = `<div class="market-item">${t('segment_empty')}</div>`;
    return;
  }
  segments.forEach(segment => {
    const node = document.createElement('article');
    node.className = 'market-item';
    node.innerHTML = `<strong>${segment.cityLabel} • ${segment.productLabel}</strong><div class="value">${segment.totalSales} / ${segment.demand}</div><small>${t('avg_price')}: ${segment.avgPrice} ₽</small>`;
    elements.segmentsOverview.appendChild(node);
  });
}

function avatarMarkup(player) {
  if (player.avatar) return `<img class="roster-avatar" src="${player.avatar}" alt="avatar" />`;
  return `<div class="roster-avatar-fallback">${(player.userName || player.name).slice(0, 2).toUpperCase()}</div>`;
}

function renderPlayerList() {
  elements.playerList.innerHTML = '';
  const players = state.room?.players || [];
  if (!players.length) {
    elements.playerList.innerHTML = `<div class="leader">${t('no_players')}</div>`;
    return;
  }
  players.forEach(player => {
    const role = player.isHost ? t('host') : player.isBot ? t('bot') : t('player');
    const readiness = player.bankrupt ? t('bankrupt') : player.ready ? t('ready_yes') : t('ready_no');
    const node = document.createElement('article');
    node.className = 'leader';
    node.innerHTML = `<div class="player-line">${avatarMarkup(player)}<div><strong>${player.userName}</strong><small>${player.name}</small><div class="badge-inline-row"><span class="mini-badge">${role}</span><span class="mini-badge ${player.ready ? 'ok' : 'warn'}">${readiness}</span></div></div></div><strong>${rub(player.money)} ₽</strong>`;
    elements.playerList.appendChild(node);
  });
}

